package com.bank.trace;

import java.util.UUID;

// The trace context propagated across service boundaries (like W3C 'traceparent').
public class TraceContext {
    private final String traceId;

    private TraceContext(String traceId) { this.traceId = traceId; }

    // Edge service generates a new trace id for the whole request.
    public static TraceContext newTrace() {
        return new TraceContext(UUID.randomUUID().toString().substring(0, 8));
    }

    // Downstream services continue the SAME trace (extracted from the header).
    public static TraceContext continueTrace(String traceId) {
        return new TraceContext(traceId);
    }

    public String getTraceId() { return traceId; }
}
