package com.bank.trace;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

// Models the central log store (Loki/Elasticsearch). Every service ships here.
public class CentralLogStore {
    // Each entry: traceId, service, structured message.
    private final List<String[]> entries = new ArrayList<>();

    public void ship(String traceId, String service, String message) {
        entries.add(new String[]{traceId, service, message});
    }

    // "Search by traceId" — reconstructs one request's journey across all services.
    public List<String> searchByTrace(String traceId) {
        return entries.stream()
            .filter(e -> e[0].equals(traceId))
            .map(e -> "[" + e[0] + "][" + e[1] + "] " + e[2])
            .collect(Collectors.toList());
    }
}
