package com.bank.trace;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Four services chained; the SAME TraceContext is propagated through each hop.
public class TransferPipeline {
    private static final Logger log = Logger.getLogger(TransferPipeline.class.getName());

    private final CentralLogStore logStore;
    private final List<Span> trace = new ArrayList<>();

    public TransferPipeline(CentralLogStore logStore) {
        this.logStore = logStore;
    }

    // Gateway: the EDGE — generates the trace id and starts propagation.
    public void handle(String fromId, String toId, BigDecimal amount) {
        TraceContext ctx = TraceContext.newTrace();
        emit(ctx, "api-gateway", "received transfer " + amount + " " + fromId + "->" + toId, 2, false);
        transferService(ctx, fromId, toId, amount);
    }

    private void transferService(TraceContext ctx, String fromId, String toId, BigDecimal amount) {
        emit(ctx, "transfer-service", "validated balance for " + fromId, 4, false);
        fraudService(ctx, fromId, amount);
        emit(ctx, "transfer-service", "debited " + fromId + ", credited " + toId, 6, false);
        notifyService(ctx, toId);
    }

    private void fraudService(TraceContext ctx, String fromId, BigDecimal amount) {
        // propagation: fraud-service CONTINUES the same trace id it received
        TraceContext child = TraceContext.continueTrace(ctx.getTraceId());
        emit(child, "fraud-service", "risk scored " + fromId + " amount " + amount + " = LOW", 38, false);
    }

    private void notifyService(TraceContext ctx, String toId) {
        emit(ctx, "notification-service", "SMS sent to " + toId, 11, false);
    }

    // Emit = write a structured log line (with traceId) + record a span. Both ship centrally.
    private void emit(TraceContext ctx, String service, String msg, long ms, boolean error) {
        logStore.ship(ctx.getTraceId(), service, msg);
        trace.add(new Span(service, ms, error));
        log.info(() -> "[trace=" + ctx.getTraceId() + "][" + service + "] " + msg);
    }

    public List<Span> getTrace() { return trace; }
}
