package com.bank.trace;

import java.math.BigDecimal;
import java.util.logging.*;

// Runnable demo: one transfer flows through 4 services; we then search logs by trace id.
public class TracingDemo {
    private static final Logger log = Logger.getLogger(TracingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — centralized logging + distributed tracing demo");

        CentralLogStore logStore = new CentralLogStore();
        TransferPipeline pipeline = new TransferPipeline(logStore);

        pipeline.handle("SAV2001", "CUR3001", new BigDecimal("50000"));

        // The trace id from the first span lets us reconstruct the whole journey.
        String traceId = logStore.searchByTrace(
            // grab any trace id from the stored logs
            pipeline.getTrace().isEmpty() ? "" : firstTraceId(logStore)).isEmpty()
            ? firstTraceId(logStore) : firstTraceId(logStore);
        traceId = firstTraceId(logStore);

        log.info("Searching central store by traceId=" + traceId + " (cross-service journey):");
        for (String line : logStore.searchByTrace(traceId)) log.info("  " + line);

        log.info("Trace waterfall (where the time went):");
        for (Span s : pipeline.getTrace()) {
            log.info(String.format("    %-22s %4dms %s",
                s.getService(), s.getDurationMs(), s.isError() ? "ERROR" : "ok"));
        }
    }

    // Helper: read the trace id of the first shipped log entry.
    private static String firstTraceId(CentralLogStore store) {
        for (String combined : store.searchByTrace(peekAnyTrace(store))) {
            return combined.substring(1, combined.indexOf(']'));
        }
        return peekAnyTrace(store);
    }

    private static String peekAnyTrace(CentralLogStore store) {
        // In this demo all entries share one trace; find it by scanning a known service line.
        java.util.List<String> all = store.searchByTrace("");
        return all.isEmpty() ? "" : "";
    }
}
